def fac (x j : ℕ) := if j=0 then 1 else boost (P.probed n P.p.T x)
def newMat (x y : ℕ) :=
   let M:=P.p.M
   let w:=P.D n (x/M) (y/M)
   P.fac n (x/M) (x%M) *w*share M (y%M) (w/P.f)
def next := Stg.mk P.p (P.i+1) (copyZone P.p.M P.S) (P.newMat n)
def project (f : Vec) (x) :=
   let M:=P.p.M
   P.fac n (x/M) (x%M)*f (x/M)

